func scanFzSubsRow(scanner interface{ Scan(...any) error }, dst *FzRow, colMask uint64, p FzSubsParams) error {
	_ = colMask
	_ = p
	var item FzRow
	var scanBuf [13]any
	scanCount := 0
	effMask := colMask
	if effMask == 0 {
		effMask = FzSubsColsAll
	}
	if (effMask & (1 << 0)) != 0 {
		scanBuf[scanCount] = &item.ID
		scanCount++
	}
	if (effMask & (1 << 1)) != 0 {
		scanBuf[scanCount] = &item.Grp
		scanCount++
	}
	if (effMask & (1 << 2)) != 0 {
		scanBuf[scanCount] = &item.K1
		scanCount++
	}
	if (effMask & (1 << 3)) != 0 {
		scanBuf[scanCount] = &item.K2
		scanCount++
	}
	if (effMask & (1 << 4)) != 0 {
		scanBuf[scanCount] = &item.K3
		scanCount++
	}
	if (effMask & (1 << 5)) != 0 {
		scanBuf[scanCount] = &item.K4
		scanCount++
	}
	if (effMask & (1 << 6)) != 0 {
		scanBuf[scanCount] = &item.K5
		scanCount++
	}
	if (effMask & (1 << 7)) != 0 {
		scanBuf[scanCount] = &item.K6
		scanCount++
	}
	if (effMask & (1 << 8)) != 0 {
		scanBuf[scanCount] = &item.K7
		scanCount++
	}
	if (effMask & (1 << 9)) != 0 {
		scanBuf[scanCount] = &item.K8
		scanCount++
	}
	if (effMask & (1 << 10)) != 0 {
		scanBuf[scanCount] = &item.Tag
		scanCount++
	}
	if (effMask & (1 << 11)) != 0 {
		scanBuf[scanCount] = &item.Tag2
		scanCount++
	}
	if (effMask & (1 << 12)) != 0 {
		scanBuf[scanCount] = &item.Note
		scanCount++
	}
	scanSlice := scanBuf[:scanCount]
	if err := scanner.Scan(scanSlice...); err != nil {
		return err
	}
	*dst = item
	return nil
}

func (q *Queries) FzSubs(ctx context.Context, p FzSubsParams) ([]FzRow, error) {
	return runtime.Collect(q.FzSubsSeq(ctx, p))
}

func (q *Queries) FzSubsSeq(ctx context.Context, p FzSubsParams) iter.Seq2[FzRow, error] {
	return func(yield func(FzRow, error) bool) {
		var zero FzRow
		vk, colMask, flagMask, approxArgs := computeFzSubsKey(p)
		_ = colMask
		argBuf := runtime.AcquireArgsCap(approxArgs)
		defer runtime.ReleaseArgs(argBuf)
		if err := expandFzSubsParams(argBuf, sqlDialect, p); err != nil {
			yield(zero, err)
			return
		}
		var subsBuf [3]runtime.Query
		subsBuf[0] = p.A
		if p.ExcludeB {
			subsBuf[1] = p.B
		}
		if p.AgainA {
			subsBuf[2] = p.A
		}
		in := runtime.RenderInput{
			ColMask:  colMask,
			FlagMask: flagMask,
			Subs:     subsBuf[:],
		}
		sqlRows, ms, err := q.cache.Query(ctx, q.db, q.txCache, q.usePrepared, vk, stmtIDFzSubs, runtime.ComputeBatchShapeTag(colMask, flagMask), 0, nil, sqlDialect, descFzSubs, &in, (*argBuf)...)
		if err != nil {
			yield(zero, err)
			return
		}
		defer runtime.ReleaseRows(&sqlRows, &ms)
		var item FzRow
		for sqlRows.Next() {
			if err := scanFzSubsRow(sqlRows, &item, colMask, p); err != nil {
				runtime.ReleaseRows(&sqlRows, &ms)
				yield(zero, err)
				return
			}
			if !yield(item, nil) {
				return
			}
		}
		err = sqlRows.Err()
		runtime.ReleaseRows(&sqlRows, &ms)
		if err != nil {
			yield(zero, err)
		}
	}
}

func (pl *Pipeline) FzSubs(p FzSubsParams) *runtime.SliceFuture[FzRow] {
	vk, colMask, flagMask, approxArgs := computeFzSubsKey(p)
	argBuf := runtime.AcquireArgsCap(approxArgs)
	expandErr := expandFzSubsParams(argBuf, sqlDialect, p)
	var subsBuf [3]runtime.Query
	subsBuf[0] = p.A
	if p.ExcludeB {
		subsBuf[1] = p.B
	}
	if p.AgainA {
		subsBuf[2] = p.A
	}
	in := runtime.RenderInput{
		ColMask:  colMask,
		FlagMask: flagMask,
		Subs:     subsBuf[:],
	}
	return runtime.QueueSlice(pl.Pipeline, stmtIDFzSubs, descFzSubs, in, vk, nil, argBuf, expandErr,
		func(rs *sql.Rows, dst *FzRow) error { return scanFzSubsRow(rs, dst, colMask, p) },
	)
}

