// FzInsertRetStreamSeq runs FzInsertRet over the rows rows pulled from seq, in chunks, and yields their rows in order.
// seq provides the rows of the collection parameter.
// An empty seq inserts nothing (a successful no-op).
func (q *Queries) FzInsertRetStreamSeq(ctx context.Context, seq iter.Seq2[FzNew, error], selectCols ...uint64) iter.Seq2[FzOut, error] {
	return func(yield func(FzOut, error) bool) {
		var zero FzOut
		if seq == nil {
			yield(zero, runtime.ErrNilArgument)
			return
		}
		chunkCap := min(256, q.cache.MaxRowsPerBatch(sqlDialect, 0, 13))
		bufPtr := fzNewChunkPool.Get().(*[]FzNew)
		chunk := (*bufPtr)[:0]
		defer func() {
			clear(chunk[:cap(chunk)])
			*bufPtr = chunk[:0]
			fzNewChunkPool.Put(bufPtr)
		}()
		flushChunk := func() bool {
			if len(chunk) == 0 {
				return true
			}
			for r, err := range q.FzInsertRetSeq(ctx, chunk, selectCols...) {
				if err != nil {
					yield(zero, err)
					return false
				}
				if !yield(r, nil) {
					return false
				}
			}
			chunk = chunk[:0]
			return true
		}
		for item, err := range seq {
			if err != nil {
				yield(zero, err)
				return
			}
			chunk = append(chunk, item)
			if len(chunk) >= chunkCap {
				if !flushChunk() {
					return
				}
			}
		}
		_ = flushChunk()
	}
}

